#déterminer le plus grand commun diviseur de deux entiers relatifs non nuls par la méthode de différence

def Saisie():
    b = False
    while not(b) :
        n=int(input("Donner un entier relatif: "))
        b = n != 0
    return n

def pgcd (x,y):
    a = abs(x)
    b = abs(y)
    while a != b :
        if a > b :
            a = a - b
        else :
            b = b - a
    return a

#####################PP###########################

a = Saisie()
b = Saisie()
print("pgcd (",a,",",b,")=",pgcd(a,b))

